// Package store is the only package that talks to the database (STACKSPEC 3.2).
//
// SQLite is embedded in the process through the pure-Go modernc.org/sqlite
// driver, so the binary builds with CGO_ENABLED=0. Migrations are goose files
// embedded in the binary; queries are generated by sqlc.
package store

import (
	"context"
	"database/sql"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"sync/atomic"
	"time"

	"github.com/pressly/goose/v3"
	_ "modernc.org/sqlite" // the SQLite driver; confined to this package by depguard.

	"github.com/luis-mc/ci-runners-shared-pool/apps/controller/internal/store/sqlcgen"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

const (
	// busyTimeout is how long SQLite waits on a locked database.
	busyTimeout = 5 * time.Second
	// DefaultDeadline bounds every query that arrives without its own deadline.
	// SQLite has no statement timeout, so this is the compensating control for
	// STACKSPEC 5.6.
	DefaultDeadline = 10 * time.Second
	// DatabaseFile is the database's file name inside the data directory.
	DatabaseFile = "controller.db"
)

// Store is the database handle plus its generated queries.
type Store struct {
	db *sql.DB
	// rdb is the read pool: query_only connections, so list pages never queue behind the writers (audit P-4).
	rdb *sql.DB
	q   *sqlcgen.Queries

	// jobsGen counts the writes of jobs and runs; agg keeps the slow aggregate answers for it (aggcache.go).
	jobsGen atomic.Int64
	agg     aggCache
	samples sampleCache
}

// Open opens (creating if needed) the database in dataDir and applies pending
// migrations. The caller owns Close.
func Open(ctx context.Context, dataDir string) (*Store, error) {
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		return nil, fmt.Errorf("create data dir: %w", err)
	}
	return openPath(ctx, filepath.Join(dataDir, DatabaseFile))
}

// OpenForTests is Open without the disk flushes: the migrations of a fresh
// database take about 0.6 s with them on Linux and over 10 s on a slow Windows
// disk, which is the whole of DefaultDeadline. Nothing a test checks depends on
// the file surviving a power cut. Production code uses Open.
func OpenForTests(ctx context.Context, dataDir string) (*Store, error) {
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		return nil, fmt.Errorf("create data dir: %w", err)
	}
	return openPath(ctx, filepath.Join(dataDir, DatabaseFile), "synchronous(OFF)")
}

func openPath(ctx context.Context, path string, extraPragmas ...string) (*Store, error) {
	return openPathWith(ctx, path, func(dsn string) (*sql.DB, error) { return sql.Open("sqlite", dsn) }, extraPragmas...)
}

func openPathWith(ctx context.Context, path string, open func(dsn string) (*sql.DB, error), extraPragmas ...string) (*Store, error) {
	dsnFor := func(readOnly bool, pragmas ...string) string {
		q := url.Values{}
		for _, p := range pragmas {
			q.Add("_pragma", p)
		}
		q.Add("_pragma", fmt.Sprintf("busy_timeout(%d)", busyTimeout.Milliseconds()))
		q.Add("_pragma", "journal_mode(WAL)")
		q.Add("_pragma", "foreign_keys(1)")
		if readOnly {
			q.Add("_pragma", "query_only(1)")
		} else {
			q.Add("_txlock", "immediate")
		}
		return (&url.URL{Scheme: "file", Opaque: filepath.ToSlash(path), RawQuery: q.Encode()}).String()
	}
	dsn := dsnFor(false, extraPragmas...)

	db, err := open(dsn)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	// One writer at a time is what SQLite gives; this small pool is for writes and the reads that sit with them.
	db.SetMaxOpenConns(4)

	// WAL lets readers run beside the writer: the list queries use their own, larger, query_only pool.
	rdb, err := open(dsnFor(true))
	if err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("open read pool: %w", err)
	}
	rdb.SetMaxOpenConns(8)

	s := &Store{db: db, rdb: rdb, q: sqlcgen.New(db)}
	ctx, cancel := withDeadline(ctx)
	defer cancel()
	if err := s.Ping(ctx); err != nil {
		_ = s.Close()
		return nil, err
	}
	if err := migrate(ctx, db); err != nil {
		_ = s.Close()
		return nil, err
	}
	return s, nil
}

func migrate(ctx context.Context, db *sql.DB) error {
	sub, err := fs.Sub(migrationsFS, "migrations")
	if err != nil {
		return fmt.Errorf("migrations: %w", err)
	}
	p, err := goose.NewProvider(goose.DialectSQLite3, db, sub)
	if err != nil {
		return fmt.Errorf("migrations: %w", err)
	}
	if _, err := p.Up(ctx); err != nil {
		return fmt.Errorf("migrations: %w", err)
	}
	return nil
}

// Close closes the database.
func (s *Store) Close() error {
	rerr := s.rdb.Close()
	if err := s.db.Close(); err != nil {
		return err
	}
	return rerr
}

// Ping checks that the database answers.
func (s *Store) Ping(ctx context.Context) error {
	ctx, cancel := withDeadline(ctx)
	defer cancel()
	if err := s.db.PingContext(ctx); err != nil {
		return fmt.Errorf("database ping: %w", err)
	}
	return nil
}

// Enqueue adds a job to the queue. With a non-empty dedupeKey a second enqueue
// of the same key returns the existing job's id instead of adding another.
func (s *Store) Enqueue(ctx context.Context, kind, payload, dedupeKey string) (int64, error) {
	if kind == "" {
		return 0, errors.New("enqueue: kind is required")
	}
	ctx, cancel := withDeadline(ctx)
	defer cancel()
	return enqueue(ctx, s.q, kind, payload, dedupeKey)
}

// WithTx runs fn in one transaction: a job is enqueued in the same transaction
// as the change that needs it (STACKSPEC 7.2).
func (s *Store) WithTx(ctx context.Context, fn func(tx *Tx) error) error {
	ctx, cancel := withDeadline(ctx)
	defer cancel()
	sqlTx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	if err := fn(&Tx{ctx: ctx, q: s.q.WithTx(sqlTx)}); err != nil {
		_ = sqlTx.Rollback()
		return err
	}
	if err := sqlTx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// Tx is the set of writes available inside WithTx.
type Tx struct {
	ctx context.Context
	q   *sqlcgen.Queries
}

// Enqueue adds a job inside the transaction.
func (t *Tx) Enqueue(kind, payload, dedupeKey string) (int64, error) {
	if kind == "" {
		return 0, errors.New("enqueue: kind is required")
	}
	return enqueue(t.ctx, t.q, kind, payload, dedupeKey)
}

// Audit appends an audit entry inside the transaction.
func (t *Tx) Audit(actor, action, subject, detail string) (int64, error) {
	return t.InsertAudit(AuditEntry{Actor: actor, Action: action, TargetID: subject, Detail: detail})
}

// CountJobs returns how many jobs are in the given state.
func (s *Store) CountJobs(ctx context.Context, state string) (int64, error) {
	ctx, cancel := withDeadline(ctx)
	defer cancel()
	return s.q.CountJobsByState(ctx, state)
}

func enqueue(ctx context.Context, q *sqlcgen.Queries, kind, payload, dedupeKey string) (int64, error) {
	if payload == "" {
		payload = "{}"
	}
	var key sql.NullString
	if dedupeKey != "" {
		key = sql.NullString{String: dedupeKey, Valid: true}
	}
	id, err := q.EnqueueJob(ctx, sqlcgen.EnqueueJobParams{Kind: kind, Payload: payload, DedupeID: key})
	if err != nil {
		return 0, fmt.Errorf("enqueue: %w", err)
	}
	return id, nil
}

// withDeadline gives ctx the default deadline when it has none.
func withDeadline(ctx context.Context) (context.Context, context.CancelFunc) {
	if _, ok := ctx.Deadline(); ok {
		return ctx, func() {}
	}
	return context.WithTimeout(ctx, DefaultDeadline)
}
